SELECT CASE WHEN products.cost >= 610 THEN 'high' WHEN products.cost >= 100 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(order_items.unit_price * order_items.quantity) AS revenue, COUNT(order_items.unit_price) AS unit_price_count FROM order_items LEFT OUTER JOIN products ON order_items.product_id = products.id RIGHT OUTER JOIN suppliers ON products.supplier_id = suppliers.id GROUP BY CASE WHEN products.cost >= 610 THEN 'high' WHEN products.cost >= 100 THEN 'mid' ELSE 'low' END ORDER BY unit_price_count DESC, revenue DESC;
